package com.universalplatform.presence; import jakarta.validation.constraints.Size; import java.util.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/live-classes/{liveClassId}") class PresenceController { private final PresenceService service; PresenceController(PresenceService service){this.service=service;} @PostMapping("/heartbeat") void heartbeat(@PathVariable UUID liveClassId,@RequestBody(required=false) HeartbeatRequest r){service.heartbeat(liveClassId,r==null?"BALANCED":r.clientProfile());} @PostMapping("/leave") void leave(@PathVariable UUID liveClassId){service.leave(liveClassId);} @GetMapping("/attendance") List<PresenceService.AttendanceView> attendance(@PathVariable UUID liveClassId){return service.list(liveClassId);} @PostMapping("/attendance/finalize") void finalizeAttendance(@PathVariable UUID liveClassId){service.finalizeAttendance(liveClassId);} @PostMapping("/attendance/{membershipId}") void set(@PathVariable UUID liveClassId,@PathVariable UUID membershipId,@RequestBody SetAttendanceRequest r){service.set(liveClassId,membershipId,r.status(),r.notes());} record HeartbeatRequest(String clientProfile){} record SetAttendanceRequest(AttendanceStatus status,@Size(max=500) String notes){} }
